    // Assert
    expect(result.archivedReason).toBe('tab-close');
    expect(result.archivedAt).toBe(FIXED_TS + 9000);
    expect(result.id).toBe('run-42');
    expect(archivedRunsStore.has('run-42')).toBe(true);

