// ==== corpus/db/migrations.ts ====
import { getAppSetting, putAppSetting } from '@/db/appSettings';
import { getAllSessions, putSession } from '@/db/sessions';

const MIGRATION_V5_GUARD_KEY = 'migration-v5-done';
const MIGRATION_V5_GUARD_VALUE = 'true';

const LOCAL_STORAGE_KEY_MAP: readonly (readonly [string, string])[] = [
  ['app:font-size', 'font-size'],
  ['theme-preference', 'theme-preference'],
  ['tutorial-progress', 'tutorial-progress'],
] as const;

function formatSessionTitle(createdAt: number): string {
  return new Date(createdAt).toLocaleString();
}

async function migrateLocalStorageToIdb(): Promise<void> {
  const writes = LOCAL_STORAGE_KEY_MAP.map(
    ([lsKey, idbKey]) => [localStorage.getItem(lsKey), idbKey] as const
  ).filter((entry): entry is readonly [string, string] => entry[0] !== null);

  await Promise.all(writes.map(([value, idbKey]) => putAppSetting(idbKey, value)));
}

async function backfillSessionTitles(): Promise<void> {
  const sessions = await getAllSessions();
  const untitled = sessions.filter(s => !s.title);

  await Promise.all(
    untitled.map(session =>
      putSession({ ...session, title: formatSessionTitle(session.createdAt) })
    )
  );
}

function removeLocalStorageKeys(): void {
  LOCAL_STORAGE_KEY_MAP.forEach(([lsKey]) => {
    localStorage.removeItem(lsKey);
  });
}

export async function runV5Migration(): Promise<void> {
  try {
    const guardValue = await getAppSetting(MIGRATION_V5_GUARD_KEY);
    if (guardValue === MIGRATION_V5_GUARD_VALUE) return;

    await migrateLocalStorageToIdb();
    await backfillSessionTitles();
    await putAppSetting(MIGRATION_V5_GUARD_KEY, MIGRATION_V5_GUARD_VALUE);
    removeLocalStorageKeys();
  } catch (error) {
    console.error('[Migration] V5 migration failed:', error);
  }
}


// ==== corpus/db/prompts.ts ====
import type { PromptHistoryEntry, PromptReference, PromptSource, PromptType } from './idb';
import { getDb, promisifyRequest, transactionComplete } from './idb';

// -- Constants --

export const PROMPT_REFERENCE_CAP = 50;

const STORE_NAME = 'prompts';

// -- Input types --

export interface CapturePromptInput {
  readonly text: string;
  readonly type: PromptType;
  readonly source: PromptSource;
  readonly reference: PromptReference;
}

// -- Pure helpers --

const toHex = (buffer: ArrayBuffer): string =>
  Array.from(new Uint8Array(buffer))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');

// -- Exported functions --

export const computePromptId = async (text: string, type: PromptType): Promise<string> => {
  const encoder = new TextEncoder();
  const data = encoder.encode(`${text}\0${type}`);
  const digest = await crypto.subtle.digest('SHA-256', data);
  return toHex(digest);
};

export const getAllPrompts = async (): Promise<readonly PromptHistoryEntry[]> => {
  const db = await getDb();
  const tx = db.transaction(STORE_NAME, 'readonly');
  const store = tx.objectStore(STORE_NAME);
  return promisifyRequest(store.getAll());
};

export const capturePrompt = async (input: CapturePromptInput): Promise<void> => {
  try {
    if (input.text.trim().length === 0) return;

    const id = await computePromptId(input.text, input.type);
    const now = input.reference.usedAt;
    const db = await getDb();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);

    const existing: PromptHistoryEntry | undefined = await promisifyRequest(store.get(id));

    const entry: PromptHistoryEntry = existing
      ? {
          ...existing,
          useCount: existing.useCount + 1,
          lastUsedAt: now,
          references: [input.reference, ...existing.references].slice(0, PROMPT_REFERENCE_CAP),
        }
      : {
          id,
          text: input.text,
          type: input.type,
          firstSource: input.source,
          useCount: 1,
          firstUsedAt: now,
          lastUsedAt: now,
          references: [input.reference],
        };

    await promisifyRequest(store.put(entry));
    await transactionComplete(tx);
  } catch (err: unknown) {
    console.error('[prompts] capturePrompt failed:', err);
  }
};

export const deletePrompts = async (ids: readonly string[]): Promise<void> => {
  const db = await getDb();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  const store = tx.objectStore(STORE_NAME);
  ids.forEach(id => {
    store.delete(id);
  });
  await transactionComplete(tx);
};


