// ==== corpus/db/archivedRuns.ts ====
import type { ArchivedReason } from './idb';
import { getDb, promisifyRequest, transactionComplete } from './idb';
import type { LabRunRow } from './labRuns';

// -- Constants --

const ARCHIVED_RUNS_STORE = 'archivedRuns';
const LAB_RUNS_STORE = 'labRuns';
const ARCHIVED_AT_INDEX = 'archivedAt';

// -- Persisted shape --
// The archivedRuns store persists ArchivedLabRun (LabRunRow + archive metadata,
// carrying `cells`). Read and export paths surface this shape directly.

export type ArchivedLabRun = LabRunRow & {
  readonly archivedAt: number;
  readonly archivedReason: ArchivedReason;
};

// -- Export type --

export type RunExport = {
  readonly schema: 'aichatney.archived-run.v1';
  readonly run: ArchivedLabRun;
};

const EXPORT_SCHEMA = 'aichatney.archived-run.v1' as const;

// -- Exported functions --

export const archiveCompletedRun = async (run: LabRunRow): Promise<ArchivedLabRun> => {
  const archived: ArchivedLabRun = {
    ...run,
    archivedAt: Date.now(),
    archivedReason: 'run-complete',
  };
  const db = await getDb();
  const tx = db.transaction(ARCHIVED_RUNS_STORE, 'readwrite');
  const archivedStore = tx.objectStore(ARCHIVED_RUNS_STORE);
  await promisifyRequest(archivedStore.put(archived));
  await transactionComplete(tx);
  return archived;
};

export const archiveRun = async (run: LabRunRow): Promise<ArchivedLabRun> => {
  const archived: ArchivedLabRun = {
    ...run,
    archivedAt: Date.now(),
    archivedReason: 'tab-close',
  };
  const db = await getDb();
  const tx = db.transaction([ARCHIVED_RUNS_STORE, LAB_RUNS_STORE], 'readwrite');
  const archivedStore = tx.objectStore(ARCHIVED_RUNS_STORE);
  const labStore = tx.objectStore(LAB_RUNS_STORE);
  await promisifyRequest(archivedStore.put(archived));
  await promisifyRequest(labStore.delete(run.id));
  await transactionComplete(tx);
  return archived;
};

export const getArchivedRuns = async (opts?: {
  readonly limit?: number;
  readonly beforeArchivedAt?: number;
}): Promise<readonly ArchivedLabRun[]> => {
  const db = await getDb();
  const tx = db.transaction(ARCHIVED_RUNS_STORE, 'readonly');
  const store = tx.objectStore(ARCHIVED_RUNS_STORE);
  const index = store.index(ARCHIVED_AT_INDEX);
  const all: readonly ArchivedLabRun[] = await promisifyRequest(index.getAll());

  const beforeArchivedAt = opts?.beforeArchivedAt;
  const filtered =
    beforeArchivedAt !== undefined ? all.filter(r => r.archivedAt < beforeArchivedAt) : all;

  const sorted = [...filtered].sort((a, b) => b.archivedAt - a.archivedAt);

  return opts?.limit !== undefined ? sorted.slice(0, opts.limit) : sorted;
};

export const getArchivedRunById = async (id: string): Promise<ArchivedLabRun | undefined> => {
  const db = await getDb();
  const tx = db.transaction(ARCHIVED_RUNS_STORE, 'readonly');
  const store = tx.objectStore(ARCHIVED_RUNS_STORE);
  return promisifyRequest(store.get(id));
};

export const deleteArchivedRuns = async (ids: readonly string[]): Promise<void> => {
  const db = await getDb();
  const tx = db.transaction(ARCHIVED_RUNS_STORE, 'readwrite');
  const store = tx.objectStore(ARCHIVED_RUNS_STORE);
  ids.forEach(id => {
    store.delete(id);
  });
  await transactionComplete(tx);
};

export const buildRunExport = (
  runs: readonly ArchivedLabRun[]
): RunExport | readonly RunExport[] => {
  const exports = runs.map((run): RunExport => ({ schema: EXPORT_SCHEMA, run }));
  return exports.length === 1 ? exports[0] : exports;
};


// ==== corpus/db/backup.ts ====
import type {
  AppSettingDTO,
  AtomicSkillDTO,
  ChatMessage,
  ChatSession,
  LLMProviderConfig,
  SkillContainerDTO,
  TestRunDTO
} from './idb';
import { DB_VERSION, getDb, promisifyRequest, transactionComplete } from './idb';

export interface DatabaseExportStores {
  readonly sessions: readonly ChatSession[];
  readonly messages: readonly ChatMessage[];
  readonly providerConfigs: readonly LLMProviderConfig[];
  readonly skills: readonly AtomicSkillDTO[];
  readonly containers: readonly SkillContainerDTO[];
  readonly appSettings: readonly AppSettingDTO[];
  readonly testRuns: readonly TestRunDTO[];
}

export interface DatabaseExport {
  readonly version: number;
  readonly exportedAt: number;
  readonly stores: DatabaseExportStores;
}

export interface ImportValidation {
  readonly valid: boolean;
  readonly error?: string;
}

const STORE_NAMES = [
  'sessions',
  'messages',
  'providerConfigs',
  'skills',
  'containers',
  'appSettings',
  'testRuns',
] as const;

function getAllFromStore<T>(tx: IDBTransaction, name: string): Promise<readonly T[]> {
  return promisifyRequest(tx.objectStore(name).getAll()) as Promise<readonly T[]>;
}

/** Exports all IDB stores. API keys in providerConfigs are encrypted at rest (008-encrypted-key-store). */
export async function exportAll(): Promise<DatabaseExport> {
  const db = await getDb();
  const tx = db.transaction([...STORE_NAMES], 'readonly');

  const [sessions, messages, providerConfigs, skills, containers, appSettings, testRuns] =
    await Promise.all([
      getAllFromStore<ChatSession>(tx, 'sessions'),
      getAllFromStore<ChatMessage>(tx, 'messages'),
      getAllFromStore<LLMProviderConfig>(tx, 'providerConfigs'),
      getAllFromStore<AtomicSkillDTO>(tx, 'skills'),
      getAllFromStore<SkillContainerDTO>(tx, 'containers'),
      getAllFromStore<AppSettingDTO>(tx, 'appSettings'),
      getAllFromStore<TestRunDTO>(tx, 'testRuns'),
    ]);

  return {
    version: DB_VERSION,
    exportedAt: Date.now(),
    stores: { sessions, messages, providerConfigs, skills, containers, appSettings, testRuns },
  };
}

function isNonNullObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function validateImport(data: unknown): ImportValidation {
  if (!isNonNullObject(data)) {
    return { valid: false, error: 'Import data must be a non-null object' };
  }
  if (typeof data.version !== 'number' || data.version !== DB_VERSION) {
    return { valid: false, error: `Unsupported version: expected ${DB_VERSION}` };
  }
  if (!isNonNullObject(data.stores)) {
    return { valid: false, error: 'Missing or invalid stores object' };
  }
  const stores = data.stores;
  const missingStore = STORE_NAMES.find(name => !Array.isArray(stores[name]));
  if (missingStore !== undefined) {
    return { valid: false, error: `Store "${missingStore}" is missing or not an array` };
  }
  return { valid: true };
}

export async function importAll(data: DatabaseExport): Promise<void> {
  const db = await getDb();
  const tx = db.transaction([...STORE_NAMES], 'readwrite');

  await Promise.all(STORE_NAMES.map(name => promisifyRequest(tx.objectStore(name).clear())));

  await Promise.all(
    STORE_NAMES.flatMap(name => {
      const store = tx.objectStore(name);
      return (data.stores[name] as readonly unknown[]).map(record =>
        promisifyRequest(store.put(record))
      );
    })
  );

  await transactionComplete(tx);
}


