        oncomplete: null as (() => void) | null,
        onerror: null as (() => void) | null,
        onabort: null as (() => void) | null,
      } as unknown as IDBTransaction;

      const promise = transactionComplete(fakeTx);

      (fakeTx as unknown as { onabort: () => void }).onabort();

      await expect(promise).rejects.toBeInstanceOf(DOMException);
      await expect(promise).rejects.toThrow('Transaction aborted');
    });
  });

  // -----------------------------------------------------------------------
  // Type exports — AppSettingDTO
  // -----------------------------------------------------------------------

  describe('AppSettingDTO export', () => {
    it('should be exported as a named type from the module', async () => {
      // This test verifies that AppSettingDTO is exported from idb.ts.
      // It imports the module and checks the type is usable at compile time.
      // When AppSettingDTO is added, this import will succeed; until then,
      // the TypeScript compiler will flag the type as missing.
      const mod = await import('./idb');

      // Construct an object matching the expected AppSettingDTO shape.
      // If the type exists but has a different shape, tsc will error.
      const setting: import('./idb').AppSettingDTO = {
        id: 'uiLanguage',
        value: 'hu',
      };

      expect(setting).toEqual({ id: 'uiLanguage', value: 'hu' });
      // Verify module loaded (runtime sanity)
      expect(mod).toBeDefined();
    });
  });

  // -----------------------------------------------------------------------
  // ChatMessage DTO — pipelineTrace field
  // -----------------------------------------------------------------------

  describe('ChatMessage DTO — pipelineTrace field', () => {
    it('should accept ChatMessage without pipelineTrace (backward compatible)', async () => {
      // When pipelineTrace is added as optional, existing messages without
      // the field must still satisfy the ChatMessage interface.
      const msg: import('./idb').ChatMessage = {
        id: 'msg-1',
        sessionId: 'sess-1',
        role: 'assistant',
        content: 'Hello',
        createdAt: 1_700_000_000_000,
      };

      expect(msg.id).toBe('msg-1');
      expect(msg).not.toHaveProperty('pipelineTrace');
    });

    it('should accept ChatMessage with pipelineTrace set to null', async () => {
      // pipelineTrace?: PipelineTrace | null — null means "pipeline ran
      // but produced no trace" vs undefined meaning "no pipeline ran"
      const msg: import('./idb').ChatMessage = {
        id: 'msg-2',
        sessionId: 'sess-1',
        role: 'assistant',
        content: 'Translated response',
        createdAt: 1_700_000_000_000,
        pipelineTrace: null,
      };

      expect(msg.pipelineTrace).toBeNull();
    });

    it('should accept ChatMessage with a full pipelineTrace object', async () => {
      const msg: import('./idb').ChatMessage = {
        id: 'msg-3',
        sessionId: 'sess-1',
        role: 'assistant',
        content: 'Translated output',
        createdAt: 1_700_000_000_000,
        pipelineTrace: {
          pipelineId: 'pipe-1',
          agentType: 'translation',
          steps: [
            {
              stepId: 'translate-input',
              label: 'Translate input',
              providerId: 'ollama',
              modelId: 'gemma3:1b',
              input: 'Hello',
              output: 'Szia',
              startedAt: 1_700_000_000_000,
              endedAt: 1_700_000_001_000,
              durationMs: 1000,
              tokenCount: 5,
              status: 'completed',
              error: null,
            },
          ],
          totalDurationMs: 1000,
          status: 'completed',
        },
      };

      expect(msg.pipelineTrace?.pipelineId).toBe('pipe-1');
      expect(msg.pipelineTrace?.steps).toHaveLength(1);
    });
  });
});


// ==== corpus/db/labRuns.ts ====
// Service layer for the v8 `labRuns` IDB store (FR-032, FR-042, FR-081).
// Mirrors `db/sessions.ts` style: thin wrappers over native IDB via getDb + helpers.
// Type imports from `@/features/prompt-tester/types` are type-only (allowed by
// db/* exception — see CLAUDE_PROJECT_SPECIFIC.md import rules).

import type {
  CellResult,
  CompareMode,
  GridCols,
  GroupKey,
  ModelEntry,
  PromptEntry,
  SortKey
} from '@/features/prompt-tester/types';

import type { EvalComparisonDTO } from './idb';
import { getDb, promisifyRequest, transactionComplete } from './idb';

const STORE = 'labRuns' as const;
const UPDATED_AT_INDEX = 'updatedAt' as const;

export type LabRunRow = {
  readonly id: string;
  readonly label: string;
  readonly createdAt: number;
  readonly updatedAt: number;
  readonly configSnapshot: {
    readonly models: readonly ModelEntry[];
    readonly prompts: readonly PromptEntry[];
    readonly userPrompt: string;
  };
  readonly cells: readonly CellResult[];
  readonly selectedCellIds: readonly string[];
  readonly compareMode: CompareMode;
  readonly sort: SortKey;
  readonly group: GroupKey;
  readonly gridCols: GridCols;
  readonly evalComparison?: EvalComparisonDTO | null;
};

export async function getAllLabRuns(): Promise<readonly LabRunRow[]> {
  const db = await getDb();
  const tx = db.transaction(STORE, 'readonly');
  const idx = tx.objectStore(STORE).index(UPDATED_AT_INDEX);
  const all = await promisifyRequest<LabRunRow[]>(idx.getAll());
  return [...all].reverse();
}

export async function getLabRunById(id: string): Promise<LabRunRow | undefined> {
  const db = await getDb();
  const tx = db.transaction(STORE, 'readonly');
  const row = await promisifyRequest<LabRunRow | undefined>(tx.objectStore(STORE).get(id));
  return row;
}

export async function putLabRun(row: LabRunRow): Promise<void> {
  const db = await getDb();
  const tx = db.transaction(STORE, 'readwrite');
  const stamped: LabRunRow = { ...row, updatedAt: Date.now() };
  tx.objectStore(STORE).put(stamped);
  await transactionComplete(tx);
}

export async function deleteLabRun(id: string): Promise<void> {
  const db = await getDb();
  const tx = db.transaction(STORE, 'readwrite');
  tx.objectStore(STORE).delete(id);
  await transactionComplete(tx);
}


