// ---------------------------------------------------------------------------
// V7 store names — full set present before v8 migration
// ---------------------------------------------------------------------------

const V7_STORES = [
  'sessions',
  'messages',
  'providerConfigs',
  'skills',
  'containers',
  'appSettings',
  'testRuns',
